\title{The Anti-Fibonacci Sequence: Quadratic Growth, Cubic Partial Sums, and a Perfect-Square Spectrum}
\author{Aristotle}
\date{July 4, 2026}

\begin{document}

\begin{abstract}
The Fibonacci sequence is the archetype of \emph{addition-driven} growth: each term is the sum of its two predecessors, terms grow exponentially, and consecutive ratios converge to the golden ratio $\varphi=\tfrac{1+\sqrt5}{2}$. We study a systematic counterpoint, the \emph{anti-Fibonacci sequence} $A$, defined by the first-order recurrence $A(0)=1$, $A(n+1)=A(n)+n$, with terms $1,1,2,4,7,11,16,22,29,37,\dots$. We establish four exact structural results and their asymptotic consequences. First, $A$ has the closed form $A(n)=1+\tfrac{n(n-1)}{2}$, so it grows quadratically with density $A(n)/n^2\to\tfrac12$, and its consecutive ratio $A(n+1)/A(n)$ converges to $1$---never to the golden ratio. Second, apart from a single boundary exception at index $5$, the sequence strictly avoids being the sum of its two predecessors: $A(n)<A(n-1)+A(n-2)$ for all $n\ge6$. Third, its partial sums satisfy the exact cubic identity $6\sum_{k=0}^{n}A(k)=n^3+5n+6$, whence the normalized cumulative sum converges to the finite constant $\tfrac16$---in contrast to Fibonacci, where the same ratio diverges. Fourth, the value set of $A$ is exactly the set of integers $m$ for which $8m-7$ is a perfect square (equivalently, $m-1$ is triangular), a Diophantine fingerprint forcing the values to have natural density zero. These results portray the anti-Fibonacci sequence as a complete negative image of the Fibonacci sequence: polynomial where Fibonacci is exponential, rational where it is irrational, governed by perfect squares where it is governed by Binet's formula.
\end{abstract}

\maketitle

\section{Introduction}

The Fibonacci sequence $F(0)=0,\ F(1)=1,\ F(n+1)=F(n)+F(n-1)$ is perhaps the most recognizable integer sequence in mathematics. Its defining operation---summing the two most recent terms---produces exponential growth, a running total that is again exponential ($\sum_{k=0}^n F(k)=F(n+2)-1$), and the convergence of consecutive ratios to the golden ratio $\varphi$. Every one of these features is a symptom of iterated addition.

It is natural to ask what a sequence looks like when it is built to \emph{avoid} that operation. The concrete data $1,1,2,4,7,11,16,\dots$ is generated exactly by the first-order recurrence
\begin{equation}
A(0)=1,\qquad A(n+1)=A(n)+n. \tag{1.1}
\end{equation}
We adopt (1.1) as the definition. The successive differences are $0,1,2,3,\dots$, so $A$ accumulates the counting numbers. This paper collects the exact structural and asymptotic theory of $A$: a subtraction-free closed form (Section~\ref{sec:closed}); its asymptotics, including the absence of the golden ratio (Section~\ref{sec:asymp}); a sharp avoidance theorem (Section~\ref{sec:avoid}); an exact cubic partial-sum identity with cubic Ces\`aro density (Section~\ref{sec:sums}); and a perfect-square membership spectrum with a density-zero consequence (Section~\ref{sec:spectrum}).

\section{Definitions and Notation}

\begin{definition}[Anti-Fibonacci sequence]
The \emph{anti-Fibonacci sequence} $A:\N\to\N$ is defined by $A(0)=1$ and $A(n+1)=A(n)+n$. Its first terms are $1,1,2,4,7,11,16,22,29,37,46,56,\dots$.
\end{definition}

\begin{definition}[Triangular numbers]
The $t$-th triangular number is $T_t=\tfrac{t(t+1)}{2}=0,1,3,6,10,15,\dots$ for $t=0,1,2,\dots$.
\end{definition}

\begin{definition}[Natural density]
A set $S\subseteq\N$ has \emph{natural density} $d$ if $\tfrac1m\#\{x\in S: x<m\}\to d$ as $m\to\infty$.
\end{definition}

We write $\varphi=\tfrac{1+\sqrt5}{2}$ for the golden ratio.

\section{The Closed Form}\label{sec:closed}

\begin{theorem}[Closed form]\label{thm:closed}
For all $n\in\N$,
\begin{equation}
2\,A(n)+n=n^2+2. \tag{3.1}
\end{equation}
Equivalently, over $\R$, $A(n)=\dfrac{n^2-n+2}{2}=1+\dfrac{n(n-1)}{2}$.
\end{theorem}

\begin{proof}[Proof sketch]
Induct on $n$. The base case $n=0$ reads $2\cdot1+0=0+2$. For the step, assume $2A(k)+k=k^2+2$. Using $A(k+1)=A(k)+k$,
\[
2A(k+1)+(k+1)=2A(k)+2k+k+1=(k^2+2)+2k+1=(k+1)^2+2,
\]
completing the induction. Dividing (3.1) by $2$ and casting to $\R$ gives $A(n)=\tfrac{n^2-n+2}{2}$.
\end{proof}

\begin{remark}
The numbers $1+\binom n2$ are the \emph{central polygonal (lazy caterer) numbers}: the maximum number of regions into which $n$ straight cuts divide a disk. Thus $A$ is a shift of a classical combinatorial sequence, explaining the perfect-square and triangular-number phenomena below.
\end{remark}

\section{Asymptotics: No Golden Ratio}\label{sec:asymp}

\begin{theorem}[Quadratic density]\label{thm:qdensity}
$\displaystyle\lim_{n\to\infty}\frac{A(n)}{n^2}=\frac12.$
\end{theorem}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:closed}, for $n\ge1$, $\tfrac{A(n)}{n^2}=\tfrac{n^2-n+2}{2n^2}=\tfrac12-\tfrac{1}{2n}+\tfrac{1}{n^2}$, and the last two terms tend to $0$.
\end{proof}

\begin{theorem}[Neighbor ratio]\label{thm:ratio}
$\displaystyle\lim_{n\to\infty}\frac{A(n+1)}{A(n)}=1.$
\end{theorem}

\begin{proof}[Proof sketch]
Dividing numerator and denominator of the closed form by $n^2$,
\[
\frac{A(n+1)}{A(n)}=\frac{1+\tfrac1n+\tfrac{2}{n^2}}{1-\tfrac1n+\tfrac{2}{n^2}}\longrightarrow\frac{1}{1}=1,
\]
the denominator being eventually bounded away from $0$.
\end{proof}

\begin{theorem}[Absence of the golden ratio]
The sequence $A(n+1)/A(n)$ does not converge to $\varphi$.
\end{theorem}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:ratio} the ratio converges to $1$; limits are unique and $1\ne\varphi$.
\end{proof}

\section{Sharp Avoidance of the Predecessor Sum}\label{sec:avoid}

\begin{theorem}[Sharp avoidance]
\begin{enumerate}
\item[(i)] (Boundary) $A(5)=A(4)+A(3)$; explicitly $11=7+4$.
\item[(ii)] (Avoidance) For every $n\ge6$, $A(n)<A(n-1)+A(n-2)$; in particular $A(n)\ne A(n-1)+A(n-2)$.
\end{enumerate}
\end{theorem}

\begin{proof}[Proof sketch]
Both parts reduce to a polynomial inequality via Theorem~\ref{thm:closed}. The sum $A(n-1)+A(n-2)$ grows like $n^2$ whereas $A(n)$ grows like $n^2/2$; the difference $\bigl(A(n-1)+A(n-2)\bigr)-A(n)$ is a quadratic in $n$ that vanishes exactly at $n=5$ and is strictly positive for all $n\ge6$.
\end{proof}

\section{Cubic Partial Sums and Ces\`aro Density}\label{sec:sums}

\begin{theorem}[Cubic partial-sum identity]\label{thm:sum}
For all $n\in\N$,
\begin{equation}
6\sum_{k=0}^{n}A(k)=n^3+5n+6. \tag{6.1}
\end{equation}
Equivalently $\sum_{k=0}^{n}A(k)=\dfrac{n^3+5n+6}{6}$.
\end{theorem}

\begin{proof}[Proof sketch]
Induct on $n$; the base case $n=0$ gives $6A(0)=6$. For the step, $6\sum_{k=0}^{n+1}A(k)=(n^3+5n+6)+6A(n+1)$, and substituting $6A(n+1)=3\bigl((n+1)^2+2-(n+1)\bigr)$ from (3.1) simplifies to $(n+1)^3+5(n+1)+6$. Alternatively, sum the closed form using $\sum_{k\le n}k=\tfrac{n(n+1)}2$ and $\sum_{k\le n}k^2=\tfrac{n(n+1)(2n+1)}6$.
\end{proof}

\begin{theorem}[Cubic Ces\`aro density]\label{thm:cesaro}
$\displaystyle\lim_{n\to\infty}\frac{1}{n^3}\sum_{k=0}^{n}A(k)=\frac16.$
\end{theorem}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:sum}, $\tfrac{1}{n^3}\sum_{k=0}^n A(k)=\tfrac{n^3+5n+6}{6n^3}=\tfrac16+\tfrac{5}{6n^2}+\tfrac{1}{n^3}$, and the corrections vanish.
\end{proof}

\begin{remark}
This is the discrete antiderivative phenomenon: since $A(n)\sim\tfrac{n^2}2$ and $\int\tfrac{x^2}2\,dx=\tfrac{x^3}6$, summation promotes the value density $\tfrac12$ to the cumulative density $\tfrac16$. For genuine Fibonacci, $\tfrac{1}{n^3}\sum_{k=0}^n F(k)=\tfrac{F(n+2)-1}{n^3}\to\infty$; the anti-Fibonacci partial sums instead have finite, rational density $\tfrac16$.
\end{remark}

\section{The Perfect-Square Spectrum}\label{sec:spectrum}

\begin{lemma}[Square identity]\label{lem:square}
For all $n\in\N$, $\ 8\,A(n)=(2n-1)^2+7.$
\end{lemma}

\begin{proof}[Proof sketch]
Multiply Theorem~\ref{thm:closed} by $4$: $8A(n)+4n=4n^2+8$, so $8A(n)=4n^2-4n+8=(2n-1)^2+7$.
\end{proof}

\begin{theorem}[Square spectrum]\label{thm:spectrum}
For every $m\in\N$,
\[
m\in\operatorname{range}(A)\iff 8m-7\text{ is a perfect square}\iff \exists k\in\N,\ k^2+7=8m.
\]
Equivalently, $m$ is an anti-Fibonacci value iff $m-1$ is a triangular number.
\end{theorem}

\begin{proof}[Proof sketch]
($\Rightarrow$) If $m=A(n)$, then $8m-7=(2n-1)^2$ by Lemma~\ref{lem:square}.
($\Leftarrow$) If $k^2+7=8m$, then $k^2\equiv1\pmod8$ forces $k$ odd, $k=2j+1$; then $8m=(2j+1)^2+7=4j^2+4j+8$, so $m=\tfrac{j^2+j}{2}+1=1+\binom{j+1}{2}=A(j+1)$. The triangular reformulation follows from $A(n)-1=\binom n2=T_{n-1}$.
\end{proof}

\begin{corollary}[Density zero]
The value set $\operatorname{range}(A)$ has natural density $0$, with counting function
$\#\{m<M:m\in\operatorname{range}(A)\}\sim\sqrt{2M}$ as $M\to\infty$.
\end{corollary}

\begin{proof}[Proof sketch]
$m=A(n)<M$ holds for $n$ up to about $\sqrt{2M}$ by the closed form; dividing $\sqrt{2M}$ by $M$ gives $\sqrt{2/M}\to0$.
\end{proof}

\section{Algorithms}

\begin{algorithm}[Generation]
Compute $A(0),\dots,A(N)$ in $O(N)$ additions by iterating $A(n+1)=A(n)+n$.
\end{algorithm}

\begin{algorithm}[Membership test]
Decide $m\in\operatorname{range}(A)$ in $O(1)$ operations (plus one integer square root): return true iff $8m-7\ge0$ and $\lfloor\sqrt{8m-7}\rfloor^2=8m-7$ (Theorem~\ref{thm:spectrum}).
\end{algorithm}

\begin{algorithm}[Closed-form evaluation]
Evaluate $A(n)=1+\tfrac{n(n-1)}2$ and $\sum_{k=0}^n A(k)=\tfrac{n^3+5n+6}6$ in $O(1)$ (Theorems~\ref{thm:closed} and~\ref{thm:sum}).
\end{algorithm}

\section{Discussion and Future Directions}

\textbf{A factorial tower of cumulative densities.} Iterating summation should yield a staircase of constants: the values grow like $n^2/2$, the first cumulative sums like $n^3/6$, the second like $n^4/24$, and the $d$-fold cumulative sum should be a degree-$(d+2)$ polynomial with leading coefficient $1/(d+2)!$, since repeated summation is a discrete antiderivative.

\textbf{Perfect-square membership as a fingerprint of quadratic growth.} A greedy additive-avoidance sequence should have a value set of the form ``the $m$ for which a fixed quadratic $Q(m)$ is a perfect square'' iff the sequence is eventually a quadratic polynomial, with $Q$ forced by its discriminant.

\textbf{The avoided-sum shadow has density zero.} The values a term refuses to become simplify to shifted squares; this shadow set should have natural density zero and counting function asymptotic to $\sqrt{2m}$.

\section{Conclusion}

The anti-Fibonacci sequence $A(n)=1+\tfrac{n(n-1)}2$ is a complete structural negative of the Fibonacci sequence: quadratic with density $\tfrac12$, neighbor ratios tending to $1$ rather than $\varphi$, predecessor-sum avoidance for all $n\ge6$, exact cubic partial sums with cumulative density $\tfrac16$, and a value set equal to $\{m:8m-7\text{ is a perfect square}\}$ of density zero. Where Fibonacci is exponential, irrational, and golden, the anti-Fibonacci sequence is polynomial, rational, and quadratic.

