function ANTI_FIB_SEQUENCE(N):
    seq <- [1]
    for n from 0 to N-1:
        seq.append(seq[last] + n)
    return seq

function ANTI_FIB_VALUE(n):
    return 1 + n*(n-1)//2
function ANTI_FIB_PARTIAL_SUM(n):
    return (n^3 + 5*n + 6)//6
